import { describe, expect, it } from "vitest";
import { headerProblems, typesStep } from "./worker-types";

const SCRIPT =
  "rm -f worker-configuration.d.ts && wrangler types --env-file=/dev/null --env-interface=GeneratedEnv";

/** The first lines of a generated file, as wrangler 4.158 writes them. */
function generated(command: string): string {
  return [
    "/* eslint-disable */",
    `// Generated by Wrangler by running \`${command}\` (hash: 3ffb69f05f2506d45186ef501abc0c29)`,
    "// Runtime types generated with workerd@1.20261104.1 2026-06-01",
    "interface __BaseEnv_GeneratedEnv {",
  ].join("\n");
}

describe("worker-types", () => {
  it("reads the `wrangler types` step of the types script", () => {
    expect(typesStep(SCRIPT)).toEqual([
      "wrangler",
      "types",
      "--env-file=/dev/null",
      "--env-interface=GeneratedEnv",
    ]);
    expect(typesStep("rm -f worker-configuration.d.ts")).toBeUndefined();
  });

  it("accepts a file the types script generated", () => {
    expect(
      headerProblems(
        generated("wrangler types --env-file=/dev/null --env-interface=GeneratedEnv"),
        SCRIPT,
      ),
    ).toEqual([]);
  });

  it("refuses a file a plain `wrangler types` generated, which reads .dev.vars", () => {
    expect(headerProblems(generated("wrangler types"), SCRIPT)).toEqual([
      "apps/api/worker-configuration.d.ts was generated by `wrangler types`, not the `types` script's `wrangler types --env-file=/dev/null --env-interface=GeneratedEnv`",
    ]);
  });

  it("fails loudly on a header it cannot read, or a script without the step", () => {
    expect(headerProblems("interface Env {}\n", SCRIPT)[0]).toMatch(/update HEADER/);
    expect(headerProblems(generated("wrangler types"), "tsc -b")).toEqual([
      "the apps/api `types` script has no `wrangler types` step",
    ]);
  });
});
